  "type": "module",
  "bin": {
    "jsontosdk-mcp-server": "dist/index.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "start": "node dist/index.js",
    "prepare": "tsc"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.29.0",
    "zod": "^3.23.8"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "typescript": "^5.7.2"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/SolvoHQ/jsontosdk-mcp.git"
  },
  "homepage": "https://jsontosdk.vercel.app",
  "keywords": [
    "mcp",
    "model-context-protocol",
    "json",
    "typescript",
    "zod",
    "code-generation",
    "claude",
    "llm-tools"
  ]
}

#!/usr/bin/env node
// Smoke test: spawn the MCP server, run the standard MCP JSON-RPC handshake,
// list tools, and invoke `json_to_typescript` against the live endpoint.
// Prints each response as it arrives. Exits 0 on success, 1 on any failure.

import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const serverPath = join(__dirname, "dist", "index.js");

const child = spawn("node", [serverPath], {
  stdio: ["pipe", "pipe", "inherit"],
});

let buffer = "";
const pending = new Map();
let nextId = 1;

function send(method, params, id = nextId++) {
  const msg = { jsonrpc: "2.0", id, method, params };
  child.stdin.write(JSON.stringify(msg) + "\n");
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject });
  });
}

function sendNotification(method, params) {
  const msg = { jsonrpc: "2.0", method, params };
  child.stdin.write(JSON.stringify(msg) + "\n");
}

child.stdout.on("data", (chunk) => {
  buffer += chunk.toString("utf8");
  let idx;
  while ((idx = buffer.indexOf("\n")) >= 0) {
    const line = buffer.slice(0, idx);
    buffer = buffer.slice(idx + 1);
    if (!line.trim()) continue;
    try {
      const msg = JSON.parse(line);
      if (msg.id != null && pending.has(msg.id)) {
        const { resolve, reject } = pending.get(msg.id);
        pending.delete(msg.id);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      }
    } catch (e) {
      console.error("Failed to parse line:", line, e);
    }
  }
});

const samplePayload = JSON.stringify({
  id: 1,
  name: "Ada",
  email: "ada@example.com",
  joinedAt: "2026-01-12T08:00:00Z",
  posts: [{ title: "Hello", views: 42 }],
});

try {
  const initResult = await send("initialize", {
    protocolVersion: "2024-11-05",
    capabilities: {},
    clientInfo: { name: "smoke-test", version: "0.0.0" },
  });
  console.log("\n=== initialize result ===");
  console.log(JSON.stringify(initResult, null, 2));

  sendNotification("notifications/initialized", {});

  const tools = await send("tools/list", {});
  console.log("\n=== tools/list result ===");
  console.log(JSON.stringify(tools, null, 2));
  if (!Array.isArray(tools.tools) || !tools.tools.some((t) => t.name === "json_to_typescript")) {
    throw new Error("json_to_typescript tool not found in tools/list response");
  }

  console.log("\n=== calling json_to_typescript with sample payload ===");
  console.log("input:", samplePayload);
  const callResult = await send("tools/call", {
    name: "json_to_typescript",
    arguments: { json: samplePayload },
  });
  console.log("\n=== tools/call result ===");
  console.log(JSON.stringify(callResult, null, 2));

  if (callResult.isError) {
    console.error("\nTool returned isError=true");
    process.exitCode = 1;
  } else if (!callResult.structuredContent?.types || !callResult.structuredContent?.schema) {
    console.error("\nMissing types/schema in structuredContent");
    process.exitCode = 1;
  } else {
    console.log("\n=== SMOKE TEST PASSED ===");
  }
} catch (e) {
  console.error("Smoke test failed:", e);
  process.exitCode = 1;
} finally {
  child.kill("SIGTERM");
}

