#!/usr/bin/env node
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";

const API_BASE = process.env.JSONTOSDK_API_BASE || "https://jsontosdk.vercel.app";
const REQUEST_TIMEOUT_MS = 60_000;

const JsonToTypescriptInputSchema = {
  json: z
    .string()
    .min(1, "json input is empty")
    .max(100 * 1024, "json input exceeds 100 KB (server limit)")
    .describe(
      "A JSON sample (one full API response or fixture). Must be valid JSON. Up to ~100 KB.",
    ),
};

const JsonToTypescriptOutputSchema = {
  types: z
    .string()
    .describe(
      "TypeScript source: only `export interface` declarations, child-first ordered, PascalCase names inferred from context.",
    ),
  schema: z
    .string()
    .describe(
      "TypeScript source for matching Zod schemas: starts with `import { z } from \"zod\";`, then `export const FooSchema = z.object({...});`.",
    ),
};

type ToolResult = {
  content: { type: "text"; text: string }[];
  structuredContent?: { types: string; schema: string };
  isError?: boolean;
};

async function callGenerate(json: string): Promise<
  | { ok: true; types: string; schema: string }
  | { ok: false; status: number | null; message: string }
> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const res = await fetch(`${API_BASE}/api/generate`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify({ json }),
      signal: controller.signal,
    });
    const text = await res.text();
    let body: any = null;
    try {
      body = text ? JSON.parse(text) : null;
    } catch {
      // non-JSON response; carry text through
    }
    if (!res.ok) {
      const apiError = (body && typeof body.error === "string" && body.error) || text || `HTTP ${res.status}`;
      return { ok: false, status: res.status, message: apiError };
    }
    if (!body || typeof body.types !== "string" || typeof body.schema !== "string") {
      return {
        ok: false,
        status: res.status,
        message: "Malformed response from jsontosdk API (missing types/schema).",
      };
    }
    return { ok: true, types: body.types, schema: body.schema };
  } catch (e: any) {
    if (e?.name === "AbortError") {
      return { ok: false, status: null, message: `Request timed out after ${REQUEST_TIMEOUT_MS / 1000}s.` };
    }
    return { ok: false, status: null, message: `Network error reaching jsontosdk: ${e?.message || String(e)}` };
  } finally {
    clearTimeout(timer);
  }
}

function formatErrorForLLM(status: number | null, message: string): string {
  if (status === 429) {
    return `jsontosdk rate limit hit (20 requests/hour per IP). ${message}\n\nWhat to tell the user: the public jsontosdk endpoint is rate-limited so abuse can't run up the LLM bill. Wait ~an hour, or run the tool against a self-hosted instance by setting JSONTOSDK_API_BASE in the MCP server's env.`;
  }
  if (status === 413) {
    return `Input too large: ${message}\n\nThe jsontosdk endpoint accepts JSON up to 100 KB per request. Trim the sample (drop repeated array elements; one or two are enough for type inference).`;
  }
  if (status === 400) {
    return `Bad input: ${message}\n\nThe JSON string must parse cleanly. Common causes: stray trailing commas, unquoted keys, single quotes instead of double.`;
  }
  if (status === 500 || status === 502 || status === 503) {
    return `Upstream LLM call failed: ${message}\n\njsontosdk delegates type inference to Claude Haiku. This is usually transient — retry in a few seconds. Persistent 500s mean the server's Anthropic key is missing or invalid.`;
  }
  if (status === null) {
    return `Could not reach jsontosdk: ${message}\n\nCheck network connectivity. The default endpoint is https://jsontosdk.vercel.app — override with JSONTOSDK_API_BASE if running self-hosted.`;
  }
  return `jsontosdk returned HTTP ${status}: ${message}`;
}

function renderText(types: string, schema: string): string {
  return [
    "# Generated TypeScript",
    "",
    "## Interfaces (`types.ts`)",
    "",
    "```typescript",
    types,
    "```",
    "",
    "## Zod schemas (`schema.ts`)",
    "",
    "```typescript",
    schema,
    "```",
    "",
    "Run `npm install zod` to use the schema file. Both blocks are written child-first, so each declaration is defined before it is referenced.",
  ].join("\n");
}

const server = new McpServer({
  name: "jsontosdk-mcp-server",
  version: "0.1.0",
});

server.registerTool(
  "json_to_typescript",
  {
    title: "JSON to TypeScript + Zod",
    description: `Convert a JSON sample into production-grade TypeScript interfaces and a matching Zod schema.

Uses Claude Haiku for naming and inference, so nested objects get sensible PascalCase names (e.g. \`posts: [{...}]\` becomes \`Post[]\`, not \`_C1[]\` like quicktype.io produces). Detects ISO dates, URLs, and emails as string subtypes.

Args:
  - json (string): A JSON sample — one full API response or fixture. Must parse cleanly. Up to ~100 KB.

Returns:
  Structured content with shape:
  {
    "types": string,   // TypeScript source: only \`export interface\` declarations, child-first ordered
    "schema": string   // TypeScript source: \`import { z } from "zod";\` then \`export const FooSchema = z.object({...})\` declarations
  }

  The text content is a markdown-formatted view of the same two files.

Examples:
  - Use when: "Generate types from this Stripe webhook payload: { ... }"
  - Use when: "I have a JSON response from a partner API, give me typed interfaces and Zod schemas"
  - Don't use when: the user wants Python / Go / Rust output — this tool emits TypeScript only.
  - Don't use when: the user has an OpenAPI spec — use an OpenAPI codegen tool instead.

Error handling:
  - Returns a structured error message if the public endpoint is rate-limited (20/hr/IP) — wait or self-host.
  - Returns a structured error if the JSON exceeds 100 KB — trim the sample.
  - Returns a structured error if the JSON is malformed — fix the input.`,
    inputSchema: JsonToTypescriptInputSchema,
    outputSchema: JsonToTypescriptOutputSchema,
    annotations: {
      readOnlyHint: true,
      destructiveHint: false,
      idempotentHint: false,
      openWorldHint: true,
    },
  },
  async ({ json }): Promise<ToolResult> => {
    try {
      JSON.parse(json);
    } catch (e: any) {
      return {
        content: [
          {
            type: "text",
            text: `Bad input: the \`json\` argument is not valid JSON (${e?.message || "parse error"}). The tool needs a JSON string that parses cleanly. Common causes: stray trailing commas, unquoted keys, single quotes instead of double.`,
          },
        ],
        isError: true,
      };
    }
    const result = await callGenerate(json);
    if (!result.ok) {
      return {
        content: [{ type: "text", text: formatErrorForLLM(result.status, result.message) }],
        isError: true,
      };
    }
    const output = { types: result.types, schema: result.schema };
    return {
      content: [{ type: "text", text: renderText(output.types, output.schema) }],
      structuredContent: output,
    };
  },
);

async function main() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error(`jsontosdk-mcp-server v0.1.0 listening on stdio (endpoint: ${API_BASE})`);
}

main().catch((err) => {
  console.error("Fatal error starting jsontosdk-mcp-server:", err);
  process.exit(1);
});
